#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    if (argc > 65) {
        puts("TOO_MANY");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }
    const char *first = argv[1];
    size_t pos = 0;
    while (first[pos] != '\0') {
        char c = first[pos];
        int all_match = 1;
        for (int i = 2; i < argc; ++i) {
            if (argv[i][pos] != c) {
                all_match = 0;
                break;
            }
        }
        if (!all_match) break;
        ++pos;
    }
    for (size_t i = 0; i < pos; ++i) putc(first[i], stdout);
    putc('\n', stdout);
    return 0;
}
